def _transcribe(args: argparse.Namespace) -> int:
    if args.insert:
        raise SpeechClientError(NATIVE_CONTROL_RETIRED)
    audio, filename = _read_audio(args.audio, args.stdin_filename)
    fields = {
        "model": args.model,
        "response_format": args.response_format,
    }
    if args.language:
        fields["language"] = args.language
    body, content_type = _encode_multipart(filename=filename, audio=audio, fields=fields)
    headers = {"Content-Type": content_type, "Accept": "application/json, text/plain"}
    api_key = os.environ.get("OMNIVOICE_API_KEY", "").strip()
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"

    response_body, _ = _open(
        request.Request(
            _join_url(args.engine_url, "/v1/audio/transcriptions"),
            data=body,
            headers=headers,
            method="POST",
        )
    )

    sys.stdout.buffer.write(response_body)
    if response_body and not response_body.endswith(b"\n"):
        sys.stdout.buffer.write(b"\n")
    return 0

def _result_segments(result: dict) -> list[dict]:
    segments = result.get("segments") or []
    if segments:
        return segments
    # Engines that only return `chunks` (transformers pipeline shape).
    out = []
    for c in result.get("chunks") or []:
        ts = c.get("timestamp") or (None, None)
        out.append({"text": c.get("text", ""), "start": ts[0], "end": ts[1]})
    return out


def _openai_segments(segments: list[dict], temperature: Optional[float]) -> list[dict]:
    """OpenAI TranscriptionSegment shape; fields an engine doesn't report
    get neutral values rather than being omitted."""
    return [
        {
            "id": i,
            "seek": int(seg.get("seek", 0) or 0),
            "start": _num(seg.get("start")),
            "end": _num(seg.get("end"), _num(seg.get("start"))),
            "text": seg.get("text", ""),
            "tokens": list(seg.get("tokens") or []),
            "temperature": _num(seg.get("temperature"), temperature or 0.0),
            "avg_logprob": _num(seg.get("avg_logprob")),
            "compression_ratio": _num(seg.get("compression_ratio")),
            "no_speech_prob": _num(seg.get("no_speech_prob")),
        }
        for i, seg in enumerate(segments)
    ]


